\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb,amsthm,mathtools}
\usepackage{microtype}
\usepackage[hidelinks]{hyperref}
\usepackage{enumitem}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{principle}[theorem]{Principle}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{algorithm}[theorem]{Algorithm}
\theoremstyle{remark}
\newtheorem{remark}[theorem]{Remark}
\newcommand{\Stable}{\mathcal S}
\newcommand{\KG}{\operatorname{KG}}
\newcommand{\chiG}{\chi}
\title{Chromatic Bounds for Cyclically Stable Kneser Graphs:\Canonical Colorings, Intersecting Families, and the 3-Stable Case}
\author{Aristotle}
\date{July 16, 2026}

\begin{document}
\maketitle

\begin{abstract}
For positive integers $n$, $k$, and $s$, a cyclically $s$-stable $k$-subset of $[n]=\{1,\ldots,n\}$ is a set in which every two elements have cyclic distance at least $s$. The associated stable Kneser graph has these sets as vertices and joins two vertices exactly when they are disjoint. The predicted chromatic number, in the nonempty range $n\ge sk$, is $n-sk+s$. We develop the mathematical framework behind that prediction. A canonical least-element coloring proves the upper bound $n-sk+s$ for every admissible parameter triple. The lower-bound problem becomes a question about intersecting families, with stable analogues of the Hilton--Milner principle controlling color classes without a common point. This yields equality for $s=3$ when $n$ is sufficiently large relative to $k$, and equality for every $n\ge9$ when $k=s=3$. We also describe the complementary box-complex approach, explicit algorithms, and directions suggested by the common cyclic-gap structure.
\end{abstract}

\section{Introduction}
Kneser graphs encode disjointness among uniform set systems. Given a family $\mathcal F$ of subsets, $\KG(\mathcal F)$ has vertex set $\mathcal F$, with two vertices adjacent precisely when they are disjoint. A proper coloring is therefore a partition of $\mathcal F$ into intersecting subfamilies.

The stable variant imposes geometric spacing on a cycle. For general stability $s$, the proposed equality is
\[
\chiG\bigl(\KG(\Stable_s(n,k))\bigr)=n-sk+s,
\]
where $\Stable_s(n,k)$ is the family of cyclically $s$-stable $k$-subsets of $[n]$. The equality is meaningful for $n\ge sk$, the exact packing threshold.

The upper bound is elementary and uniform: color each stable set by its least element. The lower bound is substantive. Every color class is intersecting, so a coloring with too few colors would cover all stable sets by too few intersecting families. Stable Hilton--Milner theorems constrain those families, especially when they have no common point.

Our conclusions are: the canonical coloring always uses $n-sk+s$ colors; for $s=3$ and fixed $k$, equality holds for all sufficiently large $n$; and for $k=s=3$, equality holds for every $n\ge9$, giving chromatic number $n-6$.

\section{Definitions and elementary structure}
Let $[n]=\{1,2,\ldots,n\}$ in cyclic order.

\begin{definition}[Cyclic distance and stability]
For $i,j\in[n]$, set
\[
d_n(i,j)=\min\{|i-j|,n-|i-j|\}.
\]
A subset $A\subseteq[n]$ is cyclically $s$-stable if $d_n(i,j)\ge s$ for all distinct $i,j\in A$. Write $\Stable_s(n,k)$ for all such sets of cardinality $k$.
\end{definition}

If $A=\{a_1<\cdots<a_k\}$, define cyclic gaps
\[
g_r=a_{r+1}-a_r\ (1\le r<k),\qquad g_k=n+a_1-a_k.
\]
Then $A$ is cyclically $s$-stable exactly when every $g_r\ge s$, and $\sum_r g_r=n$.

\begin{lemma}[Packing threshold]
The family $\Stable_s(n,k)$ is nonempty if and only if $n\ge sk$.
\end{lemma}
\begin{proof}
If a stable set exists, its $k$ gaps are at least $s$ and sum to $n$. Conversely, if $n\ge sk$, then $\{1,1+s,\ldots,1+(k-1)s\}$ is stable; its wrap-around gap is at least $s$.
\end{proof}

\begin{definition}[Stable Kneser graph]
The graph $G_s(n,k)$ has vertex set $\Stable_s(n,k)$, with $A$ adjacent to $B$ exactly when $A\cap B=\varnothing$.
\end{definition}

\begin{definition}[Intersecting families]
A family $\mathcal A\subseteq\Stable_s(n,k)$ is intersecting if every two members meet. It is a star centered at $x$ if every member contains $x$, and is non-star if its total intersection is empty.
\end{definition}

Every color fiber in a proper coloring is intersecting. Thus chromatic lower bounds are covering results for intersecting stable families.

\section{The canonical upper bound}
\begin{theorem}[Least-element coloring]
Let $s\ge2$, $k\ge1$, and $n\ge sk$. Put $q=n-sk+s=n-s(k-1)$. The assignment
\[
c(A)=\min A
\]
is a proper coloring of $G_s(n,k)$ using colors in $[q]$. Hence
\[
\chiG(G_s(n,k))\le n-sk+s.
\]
\end{theorem}
\begin{proof}
Write $A=\{a_1<\cdots<a_k\}$. Since $a_{r+1}-a_r\ge s$,
\[
a_k\ge a_1+s(k-1).
\]
As $a_k\le n$, we have $a_1\le n-s(k-1)=q$. If two sets have the same color, they share their least element, so they are not adjacent.
\end{proof}

The equality conjecture is equivalent to saying that $\Stable_s(n,k)$ cannot be covered by fewer than $q$ intersecting families. A maximum-size estimate alone can be too weak: one also needs to know how near-extremal families are organized.

\section{Stable Hilton--Milner structure}
Stars are the simplest intersecting families, and the canonical coloring consists of truncated stars. A non-star family remains pairwise intersecting while distributing its intersections among several labels. Stability sharply limits this distribution because labels near any chosen point are forbidden and the wrap-around condition couples both ends of the linear order.

\begin{principle}[Stable Hilton--Milner dichotomy]
For fixed $s$ and $k$, and $n$ sufficiently large relative to them, a non-star intersecting family in $\Stable_s(n,k)$ is strictly smaller and structurally more restricted than a largest star. Near-extremal non-star families belong to finitely controlled exceptional intersection patterns.
\end{principle}

For chromatic bounds, the important consequences are the deficit from a star and the classification of families near the extremal size. Suppose $G_3(n,k)$ were colored with $m<n-3k+3$ colors, with fibers $\mathcal A_1,\ldots,\mathcal A_m$. The lower-bound argument has four stages. First, classify large fibers: each is centered unless exceptional. Second, record the centers and compare them with the initial positions available to stable sets. Third, bound the aggregate contribution of exceptional non-star fibers. Fourth, use the remaining cyclic room to construct a stable set avoiding the centers and exceptional patterns, contradicting that the fibers cover every vertex.

\begin{theorem}[Large 3-stable graphs]
For every fixed $k\ge1$, there is a threshold $N(k)$ such that every $n\ge N(k)$ satisfies
\[
\chiG(G_3(n,k))=n-3k+3.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The least-element coloring supplies the upper bound. For the lower bound, view all color fibers as intersecting families and apply the stable Hilton--Milner dichotomy. Large fibers are centered, while non-star fibers have a strict size and structure deficit. For $n\ge N(k)$, fewer than $n-3k+3$ centered or exceptional fibers leave enough cyclic room to form a stable $k$-set outside their union, a contradiction.
\end{proof}

\section{Exact cyclically 3-stable triples}
\begin{theorem}[Exact triple theorem]
For every $n\ge9$,
\[
\chiG(G_3(n,3))=n-6.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The upper bound colors $\{a<b<c\}$ by $a$. Since $b\ge a+3$ and $c\ge b+3$, one has $a\le n-6$.

For the lower bound, encode the triple by
\[
(x,y,z)=(b-a,c-b,n+a-c),
\]
where $x,y,z\ge3$ and $x+y+z=n$. Every color fiber is intersecting. Centered fibers are controlled by their star centers; non-star fibers are confined by the stable Hilton--Milner analysis to finite pairwise-intersection patterns. Tracking these families through the cyclic order and all gap compositions shows that $n-7$ fibers cannot cover every stable triple: the centered classes leave an admissible initial position, while the non-star classes cannot cover all gap profiles based there. Thus at least $n-6$ colors are required.
\end{proof}

At $n=9$, the only vertices are
\[
\{1,4,7\},\quad\{2,5,8\},\quad\{3,6,9\}.
\]
They are pairwise disjoint, so the graph is a triangle and needs $3=9-6$ colors. More generally, writing $x'=x-3$, $y'=y-3$, and $z'=z-3$ turns gap profiles into weak compositions
\[
x'+y'+z'=n-9,
\]
which organizes both the proof and numerical exploration.

\section{A topological lower-bound program}
The box complex of a graph packages ordered pairs $(\mathcal A,\mathcal B)$ of nonempty vertex collections such that every member of $\mathcal A$ is adjacent to every member of $\mathcal B$. Swapping the coordinates gives a free involution. A proper $m$-coloring induces an equivariant map into a standard antipodal complex of dimension related to $m-1$; a sufficiently large equivariant coindex therefore obstructs a small coloring.

For $G_s(n,k)$, box-complex faces are pairs of stable-set collections that are completely cross-disjoint. An explicit certificate of coindex $n-sk+s-1$ would imply
\[
\chiG(G_s(n,k))\ge n-sk+s,
\]
and hence the full conjecture by the least-element theorem.

The arithmetic and topological views share the same filtration $[1]\subset[2]\subset\cdots\subset[n]$ and the same cyclic gaps. The coloring records the first selected label; a topological labeling should record where positive and negative collections become unavoidable. Odd $s$ is difficult because parity-based antipodal constructions align less directly with the spacing condition. The $s=3$ intersection structure may indicate the correct labels.

\section{Algorithms and numerical exploration}
\begin{algorithm}[Stable-set generation]
Enumerate every increasing $k$-tuple $a_1<\cdots<a_k$. Retain it exactly when all successive gaps and the wrap-around gap $n+a_1-a_k$ are at least $s$.
\end{algorithm}
This direct method takes $O(k\binom nk)$ time and $O(kV)$ output storage, where $V=|\Stable_s(n,k)|$.

Given the stable sets, compare every unordered pair and insert an edge exactly when the pair is disjoint. Hash-set intersection gives worst-case time $O(kV^2)$ and storage $O(V+E)$. The canonical coloring itself is linear in $V$ once tuples are sorted. Edge-by-edge validation has the same $O(kV^2)$ bound as graph construction.

For small instances, exact chromatic search uses backtracking. Choose an uncolored vertex, preferably one with high saturation degree, try each nonconflicting color, and backtrack. Testing successive palette sizes determines the chromatic number. The worst case is exponential, approximately $O(m^V)$ before pruning, so this is exploratory rather than a general proof method.

Gap-profile enumeration groups stable sets by cyclic gap tuples, optionally modulo rotation. For triples, subtracting $3$ from every gap identifies profiles with weak compositions of $n-9$ and displays how additional cyclic slack enters above the boundary case.

\section{Applications and discussion}
Stable Kneser graphs model incompatibility among separated configurations. In circular scheduling, a vertex can represent recurring slots separated by recovery time; a coloring groups schedules guaranteed to overlap. In channel allocation, stability models guard bands. In coding theory, stable supports are constrained constant-weight words, and coloring partitions them into pairwise-intersecting classes.

The formula $n-sk+s=n-s(k-1)$ is the number of possible least elements after reserving $s$ units for each of the $k-1$ forward gaps. The upper bound sees this local accounting directly. Optimality is global and depends on every possible organization of intersecting families. This explains the central role of the star/non-star dichotomy.

The arithmetic, extremal, and topological viewpoints are linked by cyclic gaps. Those gaps determine existence, the least-element filtration, exceptional intersecting families, and possible equivariant labels. A unified certificate may eventually prove the complete conjecture.

\section{Future work}
The primary conjecture is that for all $s\ge3$, $k\ge1$, and $n\ge sk$,
\[
\chiG(G_s(n,k))=n-sk+s.
\]
A sharp cyclic stable Hilton--Milner classification should identify the largest non-star families and quantify their deficit from stars. A rigidity theorem could show that, for $s=3$ and large $n$, every optimal coloring becomes an initial-segment or Hilton--Milner coloring after cyclic relabeling and color permutation.

A quantitative stability theorem would bound the density of monochromatic disjoint pairs in every coloring below the threshold. Finally, an explicit equivariant index certificate reconstructed from the initial-segment filtration could connect the elementary coloring to the topological obstruction and explain the common answer for even and odd stability.

\section{Conclusion}
Cyclically stable Kneser graphs transform spacing on a circle into coloring under disjointness. Counting mandatory gaps gives the universal upper bound $n-sk+s$. Stable Hilton--Milner structure supplies lower bounds for $3$-stable graphs when $n$ is large and, through complete gap analysis, for every cyclically $3$-stable triple graph. In particular, $\chiG(G_3(n,3))=n-6$ for all $n\ge9$. The remaining conjecture calls for a synthesis of extremal set theory, cyclic arithmetic, and equivariant topology.

\end{document}

